// Funktion zur Verteilung und Anpassung der Ströme
function distributeAndAdjust(vehicle_states, schuko_load) {
    let max_schuko_load = Math.max(...schuko_load); // Berechnung der größten Schuko-Last
    let available_current = MAX_CURRENT_PHASE - max_schuko_load; // Berechnung des verfügbaren Stroms
    let release_limits = [0, 0];
    const charging_states = [2, 3, 4]; // Fahrzeugzustände für Laden (2, 3 oder 4)
    const non_charging_states = [1, 5];


    // Verteilung der Ströme basierend auf Fahrzeugzuständen
    if (charging_states.includes(vehicle_states[0]) && non_charging_states.includes(vehicle_states[1])) {
        // Auto A lädt, Auto B ist bereit
        release_limits[0] = available_current;
    } else if (charging_states.includes(vehicle_states[1]) && non_charging_states.includes(vehicle_states[0])) {
        // Auto B lädt, Auto A ist bereit
        release_limits[1] = available_current;
    } else if (charging_states.includes(vehicle_states[0]) && charging_states.includes(vehicle_states[1])) {
        // Beide Autos laden
        release_limits[0] = available_current / 2;
        release_limits[1] = available_current / 2;
    }

    // Anpassung der Release Limits auf die gültigen Schritte
    release_limits = release_limits.map(value => {
        if (value < release_steps[0]) {
            return release_steps[0]; // Kleinster Step
        }
        for (let i = 1; i < release_steps.length; i++) {
            if (value < release_steps[i]) {
                return release_steps[i - 1]; // Vorheriger gültiger Step
            }
        }
        return release_steps[release_steps.length - 1];
    });

    return release_limits;
}

