let schuko_load = msg.payload.schuko_load || context.get("schuko_load") || [0, 0, 0];

// Maximale kombinierte Last berechnen
let max_combined_load = Math.max(...combined_load);

// Differenz zur maximal erlaubten Phasenlast berechnen
let overload = max_combined_load - MAX_CURRENT_PHASE;

// Wenn keine Überlast vorliegt, beende die Funktion
if (overload <= 0) {
    return null;
}

// Überlast auf aktive Fahrzeuge verteilen
let active_vehicles = vehicle_states.map((state, index) => state === 3 || state === 4 ? index : null).filter(v => v !== null);

// Fall 1: Nur ein Fahrzeug aktiv
if (active_vehicles.length === 1) {
    let index = active_vehicles[0];
    let new_limit = release_limits[index] - overload;

    // Abrunden auf den nächstkleineren Release Step
    release_limits[index] = release_steps.slice().reverse().find(step => step <= new_limit) || 0;
}

// Fall 2: Zwei Fahrzeuge aktiv
else if (active_vehicles.length === 2) {
    let [indexA, indexB] = active_vehicles;
    let reduction_per_vehicle = overload / 2;

    let new_limit_A = release_limits[indexA] - reduction_per_vehicle;
    let new_limit_B = release_limits[indexB] - reduction_per_vehicle;

    // Abrunden auf den nächstkleineren Release Step
    release_limits[indexA] = release_steps.slice().reverse().find(step => step <= new_limit_A) || 0;
    release_limits[indexB] = release_steps.slice().reverse().find(step => step <= new_limit_B) || 0;
}

